const FUEL_COLORS={'80':'#8f96a8','92':'#3157f6','95':'#8f7bff','98':'#cb4756',diesel:'#f2a64b',gas:'#32b98a'};
const fuelColor=t=>{const k=String(t||'').toLowerCase();return k.includes('diesel')?FUEL_COLORS.diesel:k.includes('gas')&&!k.includes('octane')?FUEL_COLORS.gas:(FUEL_COLORS[(k.match(/\d+/)||[''])[0]]||'#5b6cf0')};
const TANK_KINDS={petrol:{label:'Petrol',unit:'L'},diesel:{label:'Diesel',unit:'L'},gas:{label:'Gas',unit:'m³'},electric:{label:'Battery',unit:'kWh'}};
const kindOfFuel=t=>{const k=String(t||'').toLowerCase();return k.includes('electric')?'electric':k.includes('diesel')?'diesel':k.includes('gas')&&!k.includes('octane')?'gas':'petrol'};
const unitOfFuel=t=>TANK_KINDS[kindOfFuel(t)].unit;
const perWord=u=>u==='L'?'liter':u;
// Fuel economy for one entry of a same-vehicle, same-fuel list sorted by odometer.
// Full tank: liters used since the previous full tank / distance (exact, partial fills in between count).
// Partial fill: estimate from the previous fill (marked as an estimate).
function fuelEconomyAt(chain,idx){
  const c=chain[idx];if(!c||!(Number(c.liters)>0))return null;
  let anchor=-1;
  if(c.full_tank){for(let i=idx-1;i>=0;i--){if(chain[i].full_tank){anchor=i;break}}}
  if(anchor>=0){
    const dist=Number(c.odometer)-Number(chain[anchor].odometer);
    if(dist<=0)return null;
    let liters=0;for(let i=anchor+1;i<=idx;i++)liters+=Number(chain[i].liters)||0;
    return {economy:liters/dist*100,distance:dist,liters,estimate:false};
  }
  if(idx>0){
    const dist=Number(c.odometer)-Number(chain[idx-1].odometer);
    if(dist<=0)return null;
    return {economy:Number(c.liters)/dist*100,distance:dist,liters:Number(c.liters),estimate:true};
  }
  return null;
}

